def hungarian(graph={{graph}}, nL={{n_left}}, nR={{n_right}}):
    match_r = [-1]*nR
    def try_kuhn(u, visited):
        for v in graph[u]:
            if visited[v]: continue
            visited[v] = True
            if match_r[v] == -1 or try_kuhn(match_r[v], visited):
                match_r[v] = u; return True
        return False
    count = 0
    for u in range(nL):
        if try_kuhn(u, [False]*nR): count += 1
    return count, match_r
